//! Legacy BIFF XLS failure semantics. Valid BIFF8 fixtures are generated by
//! `scripts/make-xls-fixture.ps1` and exercised by the real-app XLS QA script so
//! the repository does not carry an opaque binary spreadsheet fixture.
use pkms_core::SourceFormat;
use pkms_worker::{WorkerRequest, WorkerResult, execute};

fn request(root: &std::path::Path) -> WorkerRequest {
    WorkerRequest {
        protocol_version: 1,
        job_id: uuid::Uuid::new_v4().to_string(),
        attempt: 1,
        lease_token: uuid::Uuid::new_v4().to_string(),
        source_version_id: uuid::Uuid::new_v4().to_string(),
        input_path: root.join("input.xls"),
        format: SourceFormat::Xls,
        output_dir: root.to_owned(),
        pdfium_library_path: None,
        content_type: None,
        ocr: None,
    }
}

fn failure_code(request: &WorkerRequest) -> String {
    match execute(request).result {
        WorkerResult::Failure { code } => code,
        other => panic!("expected a failure result, got {other:?}"),
    }
}

#[test]
fn a_file_that_is_not_an_ole_workbook_reports_the_xls_specific_failure() {
    let root = tempfile::tempdir().unwrap();
    let request = request(root.path());
    std::fs::write(&request.input_path, b"not an OLE compound workbook").unwrap();
    assert_eq!(failure_code(&request), "xls_not_container");
}
